import{_ as h}from"./chunks/brief-demo-search.C9Kho7uC.js";import{_ as c,a as m}from"./chunks/brief-demo-awards.DW_595-z.js";import{_ as g,C as p,o as a,c as u,a3 as i,b as n,w as e,a as r,E as o,a4 as d,j as l}from"./chunks/framework.Brvjz8oQ.js";const v=JSON.parse('{"title":"How the AI Film-Library Brain Works","description":"","frontmatter":{},"headers":[],"relativePath":"en/brief.md","filePath":"en/brief.md"}'),b={name:"en/brief.md"};function A(f,t,E,w,y,C){const s=p("Mermaid");return a(),u("div",null,[t[3]||(t[3]=i(`<h1 id="how-the-ai-film-library-brain-works" tabindex="-1">How the AI Film-Library Brain Works <a class="header-anchor" href="#how-the-ai-film-library-brain-works" aria-label="Permalink to &quot;How the AI Film-Library Brain Works&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Five-hundred-plus rigid genre nodes reshaped into a flexible</span></span>
<span class="line"><span>14-dimension / 400-tag taxonomy — editors find films by describing</span></span>
<span class="line"><span>what they want in one sentence. The AI says so honestly when nothing</span></span>
<span class="line"><span>truly matches, and explains itself when something does.</span></span></code></pre></div><p>Current prototype scale: <strong>667 films, 7,000+ AI tags, 3,000+ award records (18 award bodies)</strong>.</p><h2 id="_0-the-big-picture" tabindex="-1">0. The Big Picture <a class="header-anchor" href="#_0-the-big-picture" aria-label="Permalink to &quot;0. The Big Picture&quot;">​</a></h2>`,4)),(a(),n(d,null,{default:e(()=>[o(s,{id:"mermaid-10",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20ED%5B%22%F0%9F%91%A9%E2%80%8D%F0%9F%92%BB%20User%22%5D%20--%3E%20UI%5B%22%F0%9F%8C%90%20Frontend%20NiceGUI%22%5D%0A%20%20%20%20UI%20--%3E%20API%5B%22%E2%9A%99%EF%B8%8F%20Backend%20FastAPI%3Cbr%2F%3Erouters%20%2B%20services%22%5D%0A%0A%20%20%20%20subgraph%20MODELS%5B%22%F0%9F%A4%96%20AI%20model%20layer%22%5D%0A%20%20%20%20%20%20%20%20LLM%5B%22LLM%3Cbr%2F%3EGemini%20primary%20%C2%B7%20glm%20fallback%3Cbr%2F%3Etags%20films%20%C2%B7%20reads%20queries%22%5D%0A%20%20%20%20%20%20%20%20EMB%5B%22Embedding%20bge-m3%3Cbr%2F%3E1024-dim%20semantic%20vectors%22%5D%0A%20%20%20%20%20%20%20%20CE%5B%22Reranker%20bce%20cross-encoder%3Cbr%2F%3Escores%20query%20%C3%97%20candidate%20pairs%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20API%20--%3E%20LLM%0A%20%20%20%20API%20--%3E%20EMB%0A%20%20%20%20API%20--%3E%20CE%0A%20%20%20%20EMB%20--%3E%20VEC%0A%0A%20%20%20%20API%20--%3E%20SQL%5B(%22%F0%9F%97%84%EF%B8%8F%20SQLite%3Cbr%2F%3Efilms%20%C2%B7%20film_tags%2014%20dims%20%C2%B7%20awards%22)%5D%0A%20%20%20%20API%20--%3E%20VEC%5B(%22%F0%9F%A7%AD%20Qdrant%20vector%20store%3Cbr%2F%3Esemantic%20retrieval%22)%5D%0A%0A%20%20%20%20classDef%20store%20fill%3A%231f1f1f%2Cstroke%3A%23f26f21%2Ccolor%3A%23efefef%0A%20%20%20%20classDef%20llm%20fill%3A%23f26f21%2Cstroke%3A%23d4570c%2Ccolor%3A%23000%0A%20%20%20%20class%20SQL%2CVEC%20store%0A%20%20%20%20class%20LLM%2CEMB%2CCE%20llm%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[r(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=l("hr",null,null,-1)),t[5]||(t[5]=l("h2",{id:"auto-tag",tabindex:"-1"},[r("1. Auto-Tagging — what happens when a film enters the library "),l("a",{class:"header-anchor",href:"#auto-tag","aria-label":'Permalink to "1. Auto-Tagging — what happens when a film enters the library {#auto-tag}"'},"​")],-1)),(a(),n(d,null,{default:e(()=>[o(s,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20F%5B%22%F0%9F%8E%AC%20New%20film%20metadata%22%5D%20--%3E%20E%5B%22%E2%91%A0%20TMDB%20enrich%3Cbr%2F%3Eplot%20%C2%B7%20genres%20%C2%B7%20keywords%20%C2%B7%20cast%22%5D%0A%20%20%20%20E%20--%3E%20G%5B%22%E2%91%A1%20LLM%20picks%20tags%3Cbr%2F%3EGemini%20%C2%B7%2014%20dims%20%2F%20400%20tags%22%5D%0A%20%20%20%20G%20--%3E%20V%5B%22%E2%91%A2%20Tag-registry%20validation%3Cbr%2F%3Ewhitelist%20blocks%20hallucinations%22%5D%0A%20%20%20%20V%20--%3E%20H%5B%22%E2%91%A3%20Editor%20review%20(HITL)%3Cbr%2F%3Eapprove%20%2F%20reject%20%2F%20modify%22%5D%0A%20%20%20%20H%20--%3E%20EMB%5B%22%E2%91%A4%20bge-m3%20embedding%3Cbr%2F%3Etitle%2Bplot%2Btags%20%E2%86%92%20Qdrant%22%5D%0A%0A%20%20%20%20classDef%20llm%20fill%3A%23f26f21%2Cstroke%3A%23d4570c%2Ccolor%3A%23000%0A%20%20%20%20class%20G%2CEMB%20llm%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[r(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=i('<table tabindex="0"><thead><tr><th>Step</th><th>What happens</th><th>Tech</th></tr></thead><tbody><tr><td>① Gather data</td><td>Collect title and synopsis; fill gaps from an external movie database</td><td>TMDB API enrich</td></tr><tr><td>② AI reads &amp; picks tags</td><td>The AI reads everything about the film and picks fitting tags from the 14-dim / 400-tag taxonomy</td><td>Gemini (auto-fallback on rate limits)</td></tr><tr><td>③ Anti-hallucination check</td><td>The AI may only use tags that <strong>exist</strong> — anything it invents is dropped</td><td>tag-registry whitelist validation</td></tr><tr><td>④ Editor gate</td><td>Editors approve / reject / modify each tag — AI navigates, humans keep the taste</td><td>human-in-the-loop review records</td></tr><tr><td>⑤ Become a semantic vector</td><td>The whole film (title + plot + tags) is condensed into one &quot;semantic coordinate&quot; for search</td><td>bge-m3 embedding → Qdrant</td></tr></tbody></table><p>Rejected tags don&#39;t vanish — they feed a <strong>feedback wiki</strong> where the AI periodically digests which tags get rejected and why, fueling the next round of improvements.</p><hr><h2 id="query" tabindex="-1">2. Semantic Search — after the editor types one sentence <a class="header-anchor" href="#query" aria-label="Permalink to &quot;2. Semantic Search — after the editor types one sentence {#query}&quot;">​</a></h2>',4)),(a(),n(d,null,{default:e(()=>[o(s,{id:"mermaid-95",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20Q%5B%22%F0%9F%92%AC%20One-sentence%20request%22%5D%20--%3E%20U%5B%22%E2%93%AA%20LLM%20query%20understanding%3Cbr%2F%3Etaxonomy%20tag%20signals%20%2B%20HyDE%20imagined%20plot%20%2B%20keywords%22%5D%0A%20%20%20%20U%20--%3E%20S%5B%22%E2%91%A0%20Two-track%20audition%20(recall)%3Cbr%2F%3Evectors%20bge-m3%2BQdrant%20%C2%B7%20BM25%20FTS5%2Bjieba%22%5D%0A%20%20%20%20S%20--%3E%20RF%5B%22RRF%20fusion%3Cbr%2F%3Emerges%20both%20rankings%22%5D%0A%20%20%20%20RF%20--%3E%20W%5B%22%E2%91%A1%20Wildcards%20(injection)%3Cbr%2F%3Efilms%20with%20strong%20requested%20tags%20get%20a%20seat%22%5D%0A%20%20%20%20W%20--%3E%20CE%5B%22%E2%91%A2%20Cross-encoder%20rerank%3Cbr%2F%3Ebce-reranker%20scores%20each%20pair%22%5D%0A%20%20%20%20CE%20--%3E%20B%5B%22%E2%91%A3%2014-dim%20weighted%20boost%3Cbr%2F%3Ewildcards%20get%20presence%2C%20not%20rank%22%5D%0A%20%20%20%20B%20--%3E%20O%5B%22%E2%91%A4%20Confidence%20gate%20%2B%20display%20band%3Cbr%2F%3Ehonest%20scores%20%C2%B7%20explainable%20cards%22%5D%0A%0A%20%20%20%20classDef%20llm%20fill%3A%23f26f21%2Cstroke%3A%23d4570c%2Ccolor%3A%23000%0A%20%20%20%20class%20U%2CCE%20llm%0A"})]),fallback:e(()=>[...t[2]||(t[2]=[r(" Loading... ",-1)])]),_:1})),t[7]||(t[7]=i('<p>The flow works like a talent show:</p><table tabindex="0"><thead><tr><th>Step</th><th>What happens</th><th>Tech</th></tr></thead><tbody><tr><td>⓪ Understand the request</td><td>The AI parses your sentence: extracts conditions (region / awards / mood…) and imagines &quot;what the perfect match would look like&quot;</td><td>LLM query understanding: taxonomy signals + HyDE plot + keywords</td></tr><tr><td>① Audition</td><td>Two wide-recall tracks: <strong>semantic</strong> (similar meaning) + <strong>lexical</strong> (matching words)</td><td>vector recall (bge-m3 + Qdrant) + BM25 (FTS5 + jieba)</td></tr><tr><td>② Wildcards</td><td>Films that weren&#39;t recalled but carry a strong requested tag (region / awards…) are invited in, guaranteed to appear</td><td>strong-tag injection into the candidate pool</td></tr><tr><td>③ Jury rerank</td><td>A model compares every candidate against your query, one pair at a time, and reorders</td><td>cross-encoder (bce-reranker)</td></tr><tr><td>④ Condition boost</td><td>Films carrying your requested tags move up; <strong>wildcards are guaranteed presence, never rank</strong></td><td>14-dim weighted boost (no hard filters, never empties results)</td></tr><tr><td>⑤ Honest scores</td><td>No real match in the library → a warning banner and lowered scores; with real matches the cap is 95% — <strong>never a fake 100%</strong></td><td>confidence gate (vector-similarity threshold) + display band</td></tr></tbody></table><p>Every result card can explain itself: <code>matches [music][american] · semantic+imagined+lexical</code> (which conditions it satisfies + how it was found).</p><hr><h2 id="trust" tabindex="-1">3. Trust — it doesn&#39;t just find, it explains honestly <a class="header-anchor" href="#trust" aria-label="Permalink to &quot;3. Trust — it doesn&#39;t just find, it explains honestly {#trust}&quot;">​</a></h2><ul><li><strong>Anti-hallucination</strong>: every AI tag passes whitelist validation; invented tags never enter the library.</li><li><strong>Honest scores</strong>: when nothing matches it says so — while still offering its best guesses as starting points.</li><li><strong>Explainable</strong>: every result states the matched conditions and the retrieval path. No black box.</li><li><strong>Continuously measured</strong>: an automated eval harness (LLM judge) over 45 real queries scores top-5 quality at nDCG@5 ≈ 0.92–0.96; every change is scored, nothing ships on vibes.</li><li><strong>Humans in the loop</strong>: editor review + feedback wiki — AI navigates, humans steer.</li></ul><hr><h2 id="_4-tech-stack-at-a-glance" tabindex="-1">4. Tech Stack at a Glance <a class="header-anchor" href="#_4-tech-stack-at-a-glance" aria-label="Permalink to &quot;4. Tech Stack at a Glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Tool</th><th>In one line</th></tr></thead><tbody><tr><td>Tagging AI</td><td>Gemini (+OpenRouter fallback)</td><td>reads films, picks tags, parses queries</td></tr><tr><td>Semantic understanding</td><td>BAAI/bge-m3</td><td>turns films and queries into comparable &quot;semantic coordinates&quot;</td></tr><tr><td>Precision reranker</td><td>maidalun1020/bce-reranker-base_v1</td><td>scores query–candidate pairs (Chinese-domain trained)</td></tr><tr><td>Lexical search</td><td>SQLite FTS5 + jieba</td><td>keyword search over segmented Chinese, rescues proper nouns</td></tr><tr><td>Vector store</td><td>Qdrant</td><td>stores semantic coordinates, millisecond neighbor lookup</td></tr><tr><td>Database</td><td>SQLite</td><td>the source of truth for films, tags, awards</td></tr><tr><td>Awards data</td><td>award-tracker + Wikidata verification</td><td>official nominee lists → AI-structured → matched to the library</td></tr><tr><td>Deployment</td><td>Docker Compose + Traefik</td><td>the whole demo on one VPS</td></tr></tbody></table><hr><h2 id="_5-demo" tabindex="-1">5. Demo <a class="header-anchor" href="#_5-demo" aria-label="Permalink to &quot;5. Demo&quot;">​</a></h2><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><p><img src="'+h+'" alt="search demo"></p><p>&quot;Something to watch with mom on Mother&#39;s Day&quot; → result cards state matched conditions and retrieval paths; switch to &quot;Michael Jackson&quot; → no true match in the library, an honest warning plus best-guess results.</p><h3 id="auto-tagging" tabindex="-1">Auto-tagging <a class="header-anchor" href="#auto-tagging" aria-label="Permalink to &quot;Auto-tagging&quot;">​</a></h3><p><img src="'+c+'" alt="auto-tag demo"></p><p>New-film preview for &quot;Oppenheimer&quot;: TMDB enrichment → the AI suggests 11 tags (dry run, nothing written to the database).</p><h3 id="awards" tabindex="-1">Awards <a class="header-anchor" href="#awards" aria-label="Permalink to &quot;Awards&quot;">​</a></h3><p><img src="'+m+'" alt="awards demo"></p><p>18 award ceremonies ingested → expanding Oscars 2026: nominees and winners automatically matched against the CATCHPLAY+ library.</p>',20))])}const T=g(b,[["render",A]]);export{v as __pageData,T as default};
